from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class RelativeStrength(Strategy):
    rationale = (
        "Stocks with higher relative strength against a broad market index tend to outperform. "
        "Relative strength is calculated by comparing the price momentum of individual stocks to "
        "the overall market momentum. In bull markets, strong relative performance can indicate "
        "continuation of positive trends."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.is_empty():
            return Signal(information_available_at=stamp, weights={})

        nifty_returns = (history["adj_close"].tail(n=1).item() / 
                         history["adj_close"].shift(n=self._window).head(n=1).item()) - 1.0

        symbol_returns = {}
        for symbol in view.symbols:
            if symbol not in history.columns or "adj_close" not in history.columns:
                continue
            symbol_returns[symbol] = (history["adj_close"][symbol].tail(n=1).item() / 
                                      history["adj_close"][symbol].shift(n=self._window).head(n=1).item()) - 1.0

        sorted_returns = sorted(symbol_returns.items(), key=lambda x: x[1], reverse=True)
        top_n_symbols = [symbol for symbol, _ in sorted_returns[:5]]

        if not top_n_symbols:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(top_n_symbols)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in top_n_symbols}
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
